import{z as o,x as i,o as A,c as l,q as B,j as e,D as a,d as r,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"交易日的操作清单","description":"","frontmatter":{"title":"交易日的操作清单","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-daily-ops-checklist.md","filePath":"quant/qo-daily-ops-checklist.md","lastUpdated":1791063341000}'),C={name:"quant/qo-daily-ops-checklist.md"};function D(d,E,p,h,c,u){const t=i("Mermaid");return A(),l("div",null,[E[2]||(E[2]=B('<h1 id="交易日的操作清单" tabindex="-1">交易日的操作清单 <a class="header-anchor" href="#交易日的操作清单" aria-label="Permalink to &quot;交易日的操作清单&quot;">​</a></h1><div class="epigraph"><p>清单的价值不在列出做什么，而在把「忘了」变成「未勾」：每天同一组格子，错误才无处藏身。</p><footer>—— 据 Gawande, *The Checklist Manifesto*, 2009 与 RTS 6 盘前、盘中、盘后控制结构整理</footer></div><p><a href="/quant/qo-margin-clearing-ops">上一课</a>把资金变成有预算与追缴流程的供应链，更早一课把券变成有断供预案的供应链；本课把券、资金、系统装进一天的时钟。运营知识最常见的存放处是老员工的脑子，交接、扩产品线、人一请假就失效。<a href="/quant/mifid-ii-rts6">MiFID II RTS 6</a>把算法交易的盘前控制、实时监控与盘后对账写成义务，<a href="/quant/cn-custody-counter">托管与柜台</a>写过日终以清算结果为准的固定流程；本课把它们落成一张每天执行、每项可勾的操作清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量化运营的事故很少源于不会做，源于<strong>以为做了</strong>：以为清算文件到了、以为券源确认了、以为限额检查跑过了。缺口的根源是三项缺位：每项作业没有绑定的<strong>数据源</strong>——「看一眼」看的是哪张表没有定义；没有<strong>截止时刻</strong>——几点前必须完成没有约定；没有<strong>未过项的默认动作</strong>——查不出来时该停谁没有预写。三者缺任何一项，清单就退化成流程文档：贴在墙上，不产生动作。所以清单不是知识管理工具，而是控制协议。</p><p><span class="marginnote">直觉类比：「以为做了」就像出门后才开始怀疑没带钥匙——当时的「印象」毫无证据价值。清单的作用是把「带了没有」变成一格可勾选的物理动作：摸一下口袋、看一眼勾选框，记忆不再参与。</span></p>',6)),(A(),e(s,null,{default:a(()=>[n(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20ITEM%5B%22%E6%B8%85%E5%8D%95%E4%B8%8A%E7%9A%84%E4%B8%80%E9%A1%B9%E4%BD%9C%E4%B8%9A%22%5D%20--%3E%20Q1%7B%22%E7%BB%91%E5%AE%9A%E4%BA%86%E6%95%B0%E6%8D%AE%E6%BA%90%E5%90%97%22%7D%0A%20%20ITEM%20--%3E%20Q2%7B%22%E7%BA%A6%E5%AE%9A%E6%88%AA%E6%AD%A2%E6%97%B6%E5%88%BB%E5%90%97%22%7D%0A%20%20ITEM%20--%3E%20Q3%7B%22%E9%A2%84%E5%86%99%E4%BA%86%E6%9C%AA%E8%BF%87%E9%A1%B9%E5%8A%A8%E4%BD%9C%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%97%A0%22%7C%20D1%5B%22%E3%80%8C%E7%9C%8B%E4%B8%80%E7%9C%BC%E3%80%8D%E6%97%A0%E5%AE%9A%E4%B9%89%EF%BC%8C%E5%90%84%E7%9C%8B%E5%90%84%E7%9A%84%E8%A1%A8%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%97%A0%22%7C%20D2%5B%22%E9%94%99%E8%BF%87%E4%B8%8B%E6%B8%B8%E7%A1%AC%E6%88%AA%E6%AD%A2%E6%89%8D%E8%A2%AB%E5%8F%91%E7%8E%B0%22%5D%0A%20%20Q3%20--%3E%7C%22%E6%97%A0%22%7C%20D3%5B%22%E4%B8%B4%E5%9C%BA%E5%8D%B3%E5%85%B4%E5%86%B3%E7%AD%96%EF%BC%8C%E5%88%86%E5%B8%83%E5%81%8F%E4%B9%90%E8%A7%82%22%5D%0A%20%20D1%20--%3E%20DOC%5B%22%E6%B8%85%E5%8D%95%E9%80%80%E5%8C%96%E4%B8%BA%E5%A2%99%E4%B8%8A%E7%9A%84%E6%B5%81%E7%A8%8B%E6%96%87%E6%A1%A3%22%5D%0A%20%20D2%20--%3E%20DOC%0A%20%20D3%20--%3E%20DOC%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="一天的三段结构" tabindex="-1">一天的三段结构 <a class="header-anchor" href="#一天的三段结构" aria-label="Permalink to &quot;一天的三段结构&quot;">​</a></h3><p><strong>盘前</strong>：清算结果入账、可用资金与券确认（以清算为准，不以委托回执为准）、保证金预警带检查、行情与交易链路健康、策略限额与风控参数核对、当日事件（到期、分红、指数调仓）过目。<strong>盘中</strong>：监控值守、告警分级处置、异常申报或成交的即时核对、杀单功能可用——杀单不是按钮存在，是演练过（<a href="/quant/trading-kill-switch">风控闸门</a>）。<strong>盘后</strong>：三本账对账——柜台、交易所与清算、托管各一本，差异当天定性；费用与费率核对；净值复核与头寸冻结；报备数据出库；当日事故进复盘。</p><p><span class="marginnote">数字实例：三本账对账可以这样落地——柜台 5000 股、交易所回报 5000 股、托管 4500 股，差 500 股：当天必须写明差异原因（比如 T+1 过户在途），并由第二人复核定性，不许留到明天「再看看」。</span></p>',4)),(A(),e(s,null,{default:a(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E7%9B%98%E5%89%8D%EF%BC%9A%E6%B8%85%E7%AE%97%E5%85%A5%E8%B4%A6%20%2F%20%E5%88%B8%E4%B8%8E%E8%B5%84%E9%87%91%20%2F%20%E9%99%90%E9%A2%9D%20%2F%20%E9%93%BE%E8%B7%AF%E5%81%A5%E5%BA%B7%22%5D%20--%3E%20OPEN%7B%22%E5%85%A8%E9%83%A8%E5%8B%BE%E5%AE%8C%3F%22%7D%0A%20%20OPEN%20--%3E%7C%22%E6%98%AF%22%7C%20LIVE%5B%22%E7%9B%98%E4%B8%AD%EF%BC%9A%E7%9B%91%E6%8E%A7%E5%80%BC%E5%AE%88%E4%B8%8E%E5%91%8A%E8%AD%A6%E5%88%86%E7%BA%A7%22%5D%0A%20%20OPEN%20--%3E%7C%22%E5%90%A6%22%7C%20BLOCK%5B%22%E9%BB%98%E8%AE%A4%E5%8A%A8%E4%BD%9C%EF%BC%9A%E4%B8%8D%E5%BC%80%E6%96%B0%E4%BB%93%EF%BC%8C%E5%8D%87%E7%BA%A7%E5%A4%84%E7%90%86%22%5D%0A%20%20LIVE%20--%3E%20ALARM%7B%22%E5%91%8A%E8%AD%A6%3F%22%7D%0A%20%20ALARM%20--%3E%7C%22%E5%88%86%E7%BA%A7%E5%A4%84%E7%BD%AE%22%7C%20LIVE%0A%20%20ALARM%20--%3E%7C%22%E5%A4%B1%E6%8E%A7%22%7C%20KILL%5B%22%E6%9D%80%E5%8D%95%EF%BC%9A%E5%81%9C%E7%AE%97%E6%B3%95%EF%BC%8C%E6%92%A4%E6%9C%AA%E6%88%90%E4%BA%A4%E5%8D%95%22%5D%0A%20%20LIVE%20--%3E%20POST%5B%22%E7%9B%98%E5%90%8E%EF%BC%9A%E4%B8%89%E6%9C%AC%E8%B4%A6%E5%AF%B9%E8%B4%A6%20%2F%20%E8%B4%B9%E7%94%A8%20%2F%20%E5%87%80%E5%80%BC%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20POST%20--%3E%20DIFF%7B%22%E5%AF%B9%E8%B4%A6%E6%9C%89%E5%B7%AE%E5%BC%82%3F%22%7D%0A%20%20DIFF%20--%3E%7C%22%E6%98%AF%22%7C%20REC%5B%22%E5%BD%93%E5%A4%A9%E5%AE%9A%E6%80%A7%EF%BC%8C%E8%BF%9B%E5%A4%8D%E7%9B%98%22%5D%0A%20%20DIFF%20--%3E%7C%22%E5%90%A6%22%7C%20CLOSE%5B%22%E6%97%A5%E7%BB%88%EF%BC%9A%E5%86%BB%E7%BB%93%E4%B8%8E%E6%8A%A5%E5%A4%87%E5%87%BA%E5%BA%93%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>清单为什么必须绑定截止时刻：一天的链条上全是别人的硬截止——清算文件、追缴时限、报备窗口，错过任何一环，后面全段变成即兴处理。截止要写成<strong>硬掩码</strong>：过点未完成的项自动阻塞下游动作（如未完成对账则次日不开新仓），而不是靠人记得。<a href="/quant/mifid-ii-rts6">MiFID II RTS 6</a>对实时监控的告警时限、盘后控制与业务连续性的要求，翻译到机构内部就是同一张清单上的具体行。为什么未过项要有默认动作：模糊地带必然产生即兴决策，而即兴决策的分布是偏乐观的；「查不清就不开新仓」把不确定性的一侧提前封死。清单与自动化的分工也因此清楚：能自动核对的（对账勾稽、参数比对）由系统执行并在清单上留结果，差异与例外留给人工——清单记录的不是「做过」，是「差异在哪、谁定了性」。</p><p><span class="marginnote">术语翻译：「硬掩码」就是系统级的死锁——过点未勾的项自动锁住下游按钮（比如未完成对账，「开新仓」当天就点不动）。它把「忘了」从人的记忆问题变成机器的状态问题：人负责例外审批，机器负责不让例外静默发生。</span></p><p><span class="marginnote">盘前可用头寸最容易错的一格：以清算结果为准，节假日与清算异常日清算文件晚到，依赖盘前精确头寸的策略要留现金与券的缓冲，而不是假设文件永远准时。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写运营协议，不写合规手册：红线与异常交易监控是合规单元的对象，本课只保证「每小时的机器状态有人看、有记录」。清单也不替代复盘制度——事故的归档与死因分析按<a href="/quant/research-postmortem">研究复盘</a>的同模板口径走，清单只是把「当天发生了什么」的原始记录留全。清单行数本身有成本：每行检查消耗人力与开盘前的时间窗，无区分度的检查项应按季清理，否则清单会在疲劳中被整体跳过——这正是航空清单实践的核心教训（Gawande, 2009）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清单是控制协议：每项绑定数据源、截止时刻与未过项默认动作，缺一即退化为文档。</li><li>一天三段：盘前以清算结果入账并核对券、资金、限额；盘中值守与告警分级；盘后三本账对账与净值复核。</li><li>截止写成硬掩码，过点自动阻塞下游动作；杀单要演练过才算存在。</li><li>自动核对留结果，差异留给人工；清单记录差异与定性，不记录「做过」。</li><li>出处：据 Gawande, <em>The Checklist Manifesto</em>, 2009 与 RTS 6 盘前、盘中、盘后控制结构整理；日终口径见<a href="/quant/cn-custody-counter">托管与柜台</a>。</li></ul>',8))])}const F=o(C,[["render",D]]);export{m as __pageData,F as default};
